using ArnoxPay.Data;using ArnoxPay.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace ArnoxPay.Controllers;
[Authorize(Roles=SystemRoles.FinancialOfficer+","+SystemRoles.Administrator)]
public class StaffNotificationController(AppDbContext db,UserManager<AppUser> users):Controller
{
 public async Task<IActionResult> Index(){var me=await users.GetUserAsync(User);if(me is null)return Challenge();var pending=await db.Payments.Where(p=>p.Status==PaymentStatus.Pending).OrderByDescending(p=>p.SubmittedAtUtc).Take(50).ToListAsync();foreach(var p in pending){var url="/Payment/Index?status=Pending";if(!await db.StaffNotifications.AnyAsync(n=>n.UserId==me.Id&&n.Title=="Payment pending review"&&n.Message.Contains(p.Id.ToString())))db.StaffNotifications.Add(new StaffNotification{UserId=me.Id,Title="Payment pending review",Message=$"Payment #{p.Id} ({p.PaymentType}) awaits review: {p.Amount.ToString("C2",System.Globalization.CultureInfo.GetCultureInfo("en-ZA"))}.",Url=url});}var role=User.IsInRole(SystemRoles.Administrator)?SystemRoles.Administrator:SystemRoles.FinancialOfficer;var anns=await db.Announcements.Where(a=>a.IsPublished&&(a.Audience=="All"||a.Audience==role)).ToListAsync();foreach(var a in anns){var url=$"/Announcement/Read/{a.Id}";if(!await db.StaffNotifications.AnyAsync(n=>n.UserId==me.Id&&n.Url==url))db.StaffNotifications.Add(new StaffNotification{UserId=me.Id,Title="Announcement: "+a.Title,Message=a.Body.Length>480?a.Body[..480]:a.Body,Url=url});var reminderUrl=url+"?reminder=1";if(a.ReminderAtUtc.HasValue&&a.ReminderAtUtc<=DateTime.UtcNow&&!await db.StaffNotifications.AnyAsync(n=>n.UserId==me.Id&&n.Url==reminderUrl))db.StaffNotifications.Add(new StaffNotification{UserId=me.Id,Title="Reminder: "+a.Title,Message=a.DeadlineUtc.HasValue?"Deadline: "+a.DeadlineUtc.Value.ToLocalTime().ToString("g"):"Please review this announcement.",Url=reminderUrl});}await db.SaveChangesAsync();var list=await db.StaffNotifications.Where(n=>n.UserId==me.Id).OrderByDescending(n=>n.CreatedAtUtc).Take(100).AsNoTracking().ToListAsync();return View(list);}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Open(int id){var me=await users.GetUserAsync(User);if(me is null)return Challenge();var n=await db.StaffNotifications.FirstOrDefaultAsync(x=>x.Id==id&&x.UserId==me.Id);if(n is null)return NotFound();n.IsRead=true;n.ReadAtUtc=DateTime.UtcNow;await db.SaveChangesAsync();return !string.IsNullOrWhiteSpace(n.Url)&&Url.IsLocalUrl(n.Url)?Redirect(n.Url):RedirectToAction(nameof(Index));}
}
